actions.script:
const sales=ec.resource.script('component://mr-pass/screen/Sales/Sales.js')
const {token,orderId}=sales.quoteOf()
const page=sales.base(publicPath,'respond')
const params={token,orderId}
const action=sales.param('action') === 'decline' ? 'decline' : 'accept'
sales.post('respondSalesQuote',{siteId:resolvedSiteId,token,orderId,action,expectedRevision:sales.param('expectedRevision'),
    acknowledge:sales.param('acknowledge'),purchaseOrder:sales.param('purchaseOrder'),acceptorName:sales.param('acceptorName'),
    acceptorTitle:sales.param('acceptorTitle'),reason:sales.param('reason'),operationId:sales.param('operationId')},
    {path:page,params},{path:page.replace(/\/CustomerQuote$/,'/QuoteResponse'),params})

const sales=ec.resource.script('component://mr-pass/screen/Sales/Sales.js')
const asked=sales.quoteOf()
token=asked.token;orderId=asked.orderId
flash=sales.take()
view=null;failure=null
if(!token && !orderId)failure={kind:'NotFound',message:ec.l10n.localize("Open the quote from the link in our email, or from My quotes.")}
else{
    const found=sales.portal.attempt('getSalesQuote',{siteId:resolvedSiteId,token,orderId})
    if(found.error)failure=found.error.kind==='NotFound'?{kind:'NotFound',message:ec.l10n.localize("This quote is not available. The link may have expired or been replaced, or the quote is not one of yours. Your sales contact can send you a new link.")}:found.error
    else view=found.result
}
quoteQuery=token?'token='+encodeURIComponent(token):'orderId='+encodeURIComponent(orderId || '')
respondOperationId=sales.portal.operationId()
declineOperationId=sales.portal.operationId()
signInHref=passBases.account+'/Login?returnTo='+encodeURIComponent(publicPath+'?'+(view && !token ? quoteQuery : 'orderId='+encodeURIComponent(view?.quote?.orderId || orderId || '')))
